#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
TBML Expert — single-file installer / launcher / exe builder

  python RUN_ME.py              # extract + install + GUI
  python RUN_ME.py --build-exe  # extract + install + build dist/TBML_Expert/

Put tools/ (tesseract + tessdata) and optional TBML_RedFlags.xlsx beside this file.
Needs Python 3.10+ and internet once for pip.
"""

from __future__ import annotations

# =============================================================================
TESSERACT_EXE = r"tools/tesseract/tesseract.exe"
POPPLER_BIN = r"tools/poppler/bin"
TESSDATA_DIR = r"tools/tesseract/tessdata"
# =============================================================================

import base64
import os
import re
import shutil
import subprocess
import sys
import zlib
from pathlib import Path

PAYLOAD_B64 = """"""


def _die(msg: str, code: int = 1) -> None:
    print("\nERROR:", msg)
    input("Press Enter to exit...")
    raise SystemExit(code)


def extract(target: Path) -> int:
    raw = zlib.decompress(base64.b64decode(PAYLOAD_B64.encode("ascii")))
    count = 0
    for part in raw.split(b"\n--TBML-FILE--\n"):
        if not part.strip():
            continue
        nl1 = part.find(b"\n")
        nl2 = part.find(b"\n", nl1 + 1)
        rel = part[:nl1].decode("utf-8")
        size = int(part[nl1 + 1 : nl2].decode("utf-8"))
        body = part[nl2 + 1 :][:size]
        out = target / rel
        out.parent.mkdir(parents=True, exist_ok=True)
        out.write_bytes(body)
        count += 1
    return count


def ensure_python() -> None:
    if sys.version_info < (3, 10):
        _die(f"Need Python 3.10+ (found {sys.version}). Install from python.org and retry.")


def venv_python(project: Path) -> Path:
    if sys.platform.startswith("win"):
        return project / ".venv" / "Scripts" / "python.exe"
    return project / ".venv" / "bin" / "python"


def venv_pyinstaller(project: Path) -> Path:
    if sys.platform.startswith("win"):
        return project / ".venv" / "Scripts" / "pyinstaller.exe"
    return project / ".venv" / "bin" / "pyinstaller"


def ensure_venv_and_packages(project: Path, *, with_pyinstaller: bool = False) -> Path:
    py = venv_python(project)
    if not py.exists():
        print("Creating virtual environment...")
        subprocess.check_call([sys.executable, "-m", "venv", str(project / ".venv")])
        py = venv_python(project)
        if not py.exists():
            _die("Failed to create .venv")
    else:
        print("Virtual environment already exists")

    print("Installing / updating Python packages (first time can take several minutes)...")
    subprocess.check_call([str(py), "-m", "pip", "install", "--upgrade", "pip"])
    req = project / "requirements.txt"
    subprocess.check_call([str(py), "-m", "pip", "install", "-r", str(req)])
    if with_pyinstaller:
        print("Installing PyInstaller...")
        subprocess.check_call([str(py), "-m", "pip", "install", "-U", "pyinstaller"])

    print("Checking GUI toolkit (PySide6)...")
    check = subprocess.run(
        [str(py), "-c", "from PySide6.QtWidgets import QApplication; print('ok')"],
        capture_output=True,
        text=True,
    )
    if check.returncode != 0:
        _die("PySide6 failed to import after install:\n" + (check.stderr or check.stdout))
    return py


def patch_tool_paths(project: Path) -> None:
    settings = project / "config" / "settings.yaml"
    text = settings.read_text(encoding="utf-8")

    def set_yaml_key(src: str, key: str, value: str) -> str:
        pattern = rf"(?m)^(\s*{re.escape(key)}:\s*).*$"
        repl = rf'\1"{value}"' if value else rf'\1""'
        if re.search(pattern, src):
            return re.sub(pattern, repl, src, count=1)
        return src

    for key, val in (
        ("tesseract_cmd", TESSERACT_EXE.strip()),
        ("poppler_bin", POPPLER_BIN.strip()),
        ("tessdata", TESSDATA_DIR.strip()),
    ):
        text = set_yaml_key(text, key, val)

    settings.write_text(text, encoding="utf-8")
    print("OCR paths set to project tools/ folder (portable):")
    print("  Tesseract:", TESSERACT_EXE)
    print("  Poppler:  ", POPPLER_BIN)
    print("  Tessdata: ", TESSDATA_DIR)


def place_excel(project: Path) -> None:
    kb_dir = project / "knowledgebase"
    kb_dir.mkdir(parents=True, exist_ok=True)
    dest = kb_dir / "TBML_RedFlags.xlsx"
    here = Path(__file__).resolve().parent
    for candidate in (
        here / "TBML_RedFlags.xlsx",
        here / "knowledgebase" / "TBML_RedFlags.xlsx",
    ):
        if candidate.exists() and candidate.resolve() != dest.resolve():
            dest.write_bytes(candidate.read_bytes())
            print("Copied rules workbook ->", dest)
            return
    if dest.exists():
        print("Rules workbook already present:", dest)
    else:
        print("No Excel found next to RUN_ME.py — app will auto-create starter rules on first launch.")


def place_tools(project: Path) -> None:
    """Copy a sibling tools/ folder into the project so OCR travels with the app."""
    here = Path(__file__).resolve().parent
    dest = project / "tools"
    dest.mkdir(parents=True, exist_ok=True)

    src = here / "tools"
    if src.is_dir() and src.resolve() != dest.resolve():
        print("Copying tools/ next to RUN_ME.py into the project...")
        shutil.copytree(src, dest, dirs_exist_ok=True)

    tess = dest / "tesseract" / "tesseract.exe"
    poppler_ok = (dest / "poppler" / "bin" / "pdftoppm.exe").exists() or (
        dest / "poppler" / "Library" / "bin" / "pdftoppm.exe"
    ).exists()
    tessdata_dir = dest / "tesseract" / "tessdata"
    tessdata_ok = tessdata_dir.exists() and any(tessdata_dir.glob("*.traineddata"))

    print("tools/ status:")
    print("  tesseract.exe:", "OK" if tess.exists() else "MISSING -> put at tools/tesseract/tesseract.exe")
    print("  poppler:      ", "OK" if poppler_ok else "MISSING -> put pdftoppm.exe under tools/poppler/bin/")
    print(
        "  tessdata:     ",
        "OK (inside tesseract/)"
        if tessdata_ok
        else "MISSING -> put eng.traineddata in tools/tesseract/tessdata/",
    )
    if not tess.exists():
        print("WARNING: Without tools/tesseract the GUI still opens, but OCR will fail.")


def launch(py: Path, project: Path) -> int:
    print()
    print("Starting TBML Expert GUI...")
    env = os.environ.copy()
    for key, rel in (
        ("TBML_TESSERACT_CMD", TESSERACT_EXE.strip()),
        ("TBML_POPPLER_PATH", POPPLER_BIN.strip()),
        ("TESSDATA_PREFIX", TESSDATA_DIR.strip()),
    ):
        if not rel:
            continue
        path = Path(rel)
        if not path.is_absolute():
            path = project / path
        env[key] = str(path)
    return subprocess.call([str(py), "main.py"], cwd=str(project), env=env)


def build_exe(project: Path, py: Path) -> int:
    """Build onedir exe with config + knowledgebase + tools embedded."""
    print()
    print("Building shippable exe with PyInstaller (onedir / _internal)...")
    pi = venv_pyinstaller(project)
    if not pi.exists():
        subprocess.check_call([str(py), "-m", "pip", "install", "-U", "pyinstaller"])
    cmd = [
        str(pi),
        "--noconfirm",
        "--clean",
        "--windowed",
        "--onedir",
        "--name",
        "TBML_Expert",
        "--paths",
        ".",
        "--add-data",
        "config;config",
        "--add-data",
        "modules/ui/styles;modules/ui/styles",
        "--add-data",
        "knowledgebase;knowledgebase",
        "--add-data",
        "tools;tools",
        "--hidden-import",
        "modules",
        "--hidden-import",
        "modules.ui",
        "--hidden-import",
        "modules.ui.main_window",
        "--hidden-import",
        "modules.ui.pages",
        "--hidden-import",
        "modules.ui.widgets",
        "--hidden-import",
        "modules.ocr",
        "--hidden-import",
        "modules.ocr.extractor",
        "--hidden-import",
        "modules.reports",
        "--hidden-import",
        "modules.reports.narrative",
        "--hidden-import",
        "modules.reality_research",
        "--hidden-import",
        "modules.company_search",
        "--hidden-import",
        "modules.company_search.auto_verify",
        "--hidden-import",
        "modules.knowledgebase",
        "--hidden-import",
        "modules.knowledgebase.updater",
        "--hidden-import",
        "modules.rule_engine",
        "--hidden-import",
        "modules.risk_engine",
        "--hidden-import",
        "modules.memory",
        "--hidden-import",
        "modules.database",
        "--hidden-import",
        "modules.internet_classifier",
        "--hidden-import",
        "modules.investigation",
        "--hidden-import",
        "modules.plugins",
        "--hidden-import",
        "modules.utils",
        "--hidden-import",
        "modules.utils.workers",
        "--hidden-import",
        "config",
        "--exclude-module",
        "tkinter",
        "main.py",
    ]
    # Prefer spec if present (cleaner); else raw command above
    spec = project / "TBML_Expert.spec"
    if spec.exists():
        cmd = [str(pi), "--noconfirm", "--clean", str(spec.name)]
    code = subprocess.call(cmd, cwd=str(project))
    if code != 0:
        return code
    dist = project / "dist" / "TBML_Expert"
    print()
    print("Build finished.")
    print("Share this whole folder via OneDrive:")
    print(" ", dist)
    print("Recipients unzip/run: TBML_Expert.exe")
    return 0


def prepare(project: Path, *, with_pyinstaller: bool) -> Path:
    if not (project / "main.py").exists():
        print("Extracting application source into", project)
        n = extract(project)
        print(f"  Wrote {n} files")
    else:
        print("Application folder found:", project)
    place_tools(project)
    place_excel(project)
    patch_tool_paths(project)
    return ensure_venv_and_packages(project, with_pyinstaller=with_pyinstaller)


def main() -> int:
    build = "--build-exe" in sys.argv or "--build" in sys.argv
    print("=" * 60)
    print(" TBML Expert — ONE-FILE setup")
    print(" mode:", "BUILD EXE" if build else "RUN GUI")
    print("=" * 60)
    ensure_python()

    here = Path(__file__).resolve().parent
    project = here / "TBML_Expert"
    py = prepare(project, with_pyinstaller=build)
    if build:
        return build_exe(project, py)
    return launch(py, project)


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except subprocess.CalledProcessError as exc:
        _die(f"Command failed ({exc.returncode}): {exc.cmd}")
    except KeyboardInterrupt:
        print("\nCancelled.")
        raise SystemExit(130)
